SELECT p.idEmpresa, p.id, p.Tipo, p.Activo, SUM(CASE WHEN v.Activo=1 AND v.CantidadVenta=1 AND v.EquivalenciaBase=1 AND v.idUnidadVenta=p.idUnidadMedida THEN 1 ELSE 0 END) AS bases, SUM(CASE WHEN v.Activo=1 AND v.CantidadVenta=1 AND v.EquivalenciaBase=1 AND v.idUnidadVenta=p.idUnidadMedida AND v.Precio<>p.PrecioPublico THEN 1 ELSE 0 END) AS bases_precio_distinto FROM dbo.ProductosServicios p LEFT JOIN dbo.ProductosServiciosPresentacionesVenta v ON v.idEmpresa=p.idEmpresa AND v.idProductoServicio=p.id GROUP BY p.idEmpresa,p.id,p.Tipo,p.Activo